css:
.ss-cmp__w{overflow-x:auto;-webkit-overflow-scrolling:touch;margin:8px 0 28px}
.ss-cmp{width:100%;border-collapse:collapse;margin:0}
.ss-cmp th,.ss-cmp td{padding:12px 14px;border-bottom:1px solid var(--line);font-size:14.5px;line-height:1.7;text-align:left;vertical-align:top;color:var(--body-text)}
.ss-cmp thead th{font:700 11px/1 var(--font-body);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.ss-cmp tbody th{width:30%;font-weight:700;color:var(--ink)}
@media (max-width:640px){.ss-cmp th,.ss-cmp td{padding:8px;font-size:13px}}
